#!/usr/bin/env node
/**
 * 在 OpenNext 构建产物之上注入 Cloudflare Cron 调度处理器。
 *
 * 运行时机：opennextjs-cloudflare 构建完成后，wrangler deploy 之前。
 * 典型用法：npm run build:cf
 *
 * 生成 .open-next/with-cron.js，wrangler.toml 的 main 指向此文件。
 */
import { writeFileSync, existsSync } from "node:fs";

const INPUT = ".open-next/worker.js";
const OUTPUT = ".open-next/with-cron.js";

if (!existsSync(INPUT)) {
  console.error(
    `[wrap-with-cron] ERROR: ${INPUT} not found.\n` +
      "Run the OpenNext cloudflare build first (npx opennextjs-cloudflare)."
  );
  process.exit(1);
}

const content = `\
// Auto-generated by scripts/wrap-with-cron.mjs — DO NOT EDIT MANUALLY.
// Wraps the OpenNext fetch handler and adds the Cloudflare Cron Trigger
// scheduled handler for weekly menu generation (cron: "0 1 * * 0").
import openNextHandler from "./worker.js";

function getWeekMonday(scheduledTime) {
  const d = new Date(scheduledTime);
  // 0 = Sunday; shift to the most recent Monday
  const diff = d.getUTCDay() === 0 ? -6 : 1 - d.getUTCDay();
  d.setUTCDate(d.getUTCDate() + diff);
  return d.toISOString().slice(0, 10); // YYYY-MM-DD
}

export default {
  // Re-use the OpenNext handler for all HTTP traffic.
  fetch(request, env, ctx) {
    const handler =
      typeof openNextHandler.fetch === "function"
        ? openNextHandler.fetch.bind(openNextHandler)
        : openNextHandler; // fallback: handler itself is the fetch function
    return handler(request, env, ctx);
  },

  // Cloudflare Cron Trigger fires this on the schedule defined in wrangler.toml.
  // It creates a durable WeeklyGeneration Workflow instance for the upcoming week.
  async scheduled(event, env, _ctx) {
    const weekStart = getWeekMonday(event.scheduledTime);
    console.log("[cron] triggered, weekStart=" + weekStart);

    if (!env.WEEKLY_GENERATION) {
      console.error(
        "[cron] WEEKLY_GENERATION binding missing — check wrangler.toml [[workflows]]"
      );
      return;
    }

    // Idempotent: same id = same instance, so duplicate cron fires are safe.
    await env.WEEKLY_GENERATION.create({
      id: "weekly-" + weekStart,
      params: { weekStart, trigger: "cron" },
    });

    console.log("[cron] workflow created for week " + weekStart);
  },
};
`;

writeFileSync(OUTPUT, content, "utf8");
console.log("[wrap-with-cron] Written " + OUTPUT);
